import React, { useState, useEffect } from "react";
import { Box, Typography, Button, Grid, Card, CardContent } from "@mui/material";
import { useNavigate, useLocation } from "react-router-dom";

const backgroundImages = [
  "/Background19.jpg",
  "/Background20.jpg",
  "/Background21.jpg",
  "/Background22.jpg",
];

export default function HomePage({ onSelect }: { onSelect: (page: string) => void }) {
  const [currentBackground, setCurrentBackground] = useState(0);
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    // Scroll to "Book Now" section when navigating back to Home
    if (location.pathname === '/') {
      const bookNowSection = document.getElementById("book-now-section");
      if (bookNowSection) {
        bookNowSection.scrollIntoView({ behavior: "smooth" });
      }
    }
  }, [location.pathname]);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentBackground((prev) => (prev + 1) % backgroundImages.length);
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  // Function to handle scroll on button click and show card section
  const handleBookNowClick = () => {
    const cardSection = document.getElementById("card-section");
    if (cardSection) {
      const targetPosition = cardSection.offsetTop; // Get the position of the card section
      const currentPosition = window.scrollY; // Current scroll position
      const distance = targetPosition - currentPosition; // Distance to scroll
      const duration = 1000; // Duration of the scroll in milliseconds (slower scroll)

      // Function to handle smooth scroll with delay
      let start: number;
      const smoothScroll = (timestamp: number) => {
        if (!start) start = timestamp;
        const progress = timestamp - start;
        const scrollStep = (distance * progress) / duration;
        window.scrollTo(0, currentPosition + scrollStep);

        if (progress < duration) {
          requestAnimationFrame(smoothScroll); // Continue scrolling until the duration is reached
        } else {
          window.scrollTo(0, targetPosition); // Final scroll to the target position
        }
      };
      requestAnimationFrame(smoothScroll); // Start the scroll animation
    }
  };

  // Handle card click to change page
  const handleCardClick = (page: string) => {
    onSelect(page); // Update active page based on card clicked
  };

  return (
    <Box>
      {/* Home Content */}
      <Box
        id="book-now-section"
        sx={{
          padding: { xs: 2, sm: 4 },
          textAlign: "center",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          minHeight: "100vh",
          backgroundImage: `url(${backgroundImages[currentBackground]})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          transition: "background-image 0.8s ease-in-out",
        }}
      >
        <Typography
          variant="h3"
          gutterBottom
          sx={{
            fontWeight: "bold",
            color: "#b56f76",
            fontSize: { xs: "2rem", sm: "3rem" },
          }}
        >
          EVERPLAN
        </Typography>
        <Typography
          variant="h5"
          gutterBottom
          sx={{
            fontStyle: "italic",
            color: "#6B4F4F",
            fontSize: { xs: "1.2rem", sm: "1.5rem" },
          }}
        >
          Plan, Book, Celebrate—It’s That Easy!
        </Typography>

        <Button
          variant="contained"
          sx={{
            marginTop: 2,
            padding: "10px 20px",
            fontSize: "1rem",
            borderRadius: 2,
            width: "200px",
            backgroundColor: "#F7C5AD",
            color: "#fff",
            "&:hover": {
              backgroundColor: "#F7C5AD",
            },
          }}
          onClick={handleBookNowClick}
        >
          Book Now
        </Button>
      </Box>

      {/* Cardholders Section */}
      <Box
        id="card-section"
        sx={{
          padding: 4,
        }}
      >
        <Typography
          variant="h4"
          sx={{
            fontWeight: "bold",
            textAlign: "center",
            marginBottom: 3,
          }}
        >
          Explore Our Services
        </Typography>

        {/* Grid Layout for Cards */}
        <Grid container spacing={2} sx={{ justifyContent: "center" }}>
          {["venues", "hair", "makeup", "photographers", "music", "florist", "dresser", "planner"].map((tab) => (
            <Grid item xs={6} sm={4} md={3} key={tab}>
              <Card
                sx={{
                  borderRadius: 6, // Rounded corners for the card
                  boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
                  overflow: "hidden",
                  display: "flex",
                  flexDirection: "column",
                  height: "100%",
                  backgroundColor: "#fff", // White background for card
                  cursor: "pointer",
                }}
                onClick={() => handleCardClick(tab)} // Card click handler
              >
                {/* Image Section: Replace with your custom image */}
                <Box
                  sx={{
                    width: "100%",
                    aspectRatio: "4 / 3", // Maintain 4:3 aspect ratio for image part
                    backgroundImage: `url('/images/${tab}.jpg')`, // Example placeholder image
                    backgroundSize: "cover",
                    backgroundPosition: "center",
                  }}
                />
                {/* White part for title and subtitle */}
                <CardContent
                  sx={{
                    backgroundColor: "#fff",
                    padding: 2,
                    textAlign: "center",
                  }}
                >
                  <Typography
                    variant="h6"
                    sx={{
                      fontWeight: "bold",
                      fontSize: "calc(1.2vw + 0.8rem)",
                      textAlign: "center",
                      lineHeight: 1.2,
                      overflow: "hidden",
                      whiteSpace: "nowrap",
                      textOverflow: "ellipsis",
                    }}
                  >
                    {tab.charAt(0).toUpperCase() + tab.slice(1)}
                  </Typography>
                  <Typography
                    variant="body2"
                    color="text.secondary"
                    sx={{
                      fontSize: "calc(0.8vw + 0.6rem)",
                      textAlign: "center",
                      lineHeight: 1,
                      overflow: "hidden",
                      whiteSpace: "nowrap",
                      textOverflow: "ellipsis",
                      marginTop: 1,
                    }}
                  >
                    Description for {tab}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Box>
    </Box>
  );
}
